// Plan mensual de cómputo: 4 instancias estables y picos ocasionales.
// Precios FICTICIOS del enunciado (USD por hora-instancia); no son precios de AWS.
export const precios = [
  { item: "bajo-demanda", unit: "hora-instancia", pricePerUnitUsd: 0.1 },
  { item: "savings-plan", unit: "hora-instancia", pricePerUnitUsd: 0.07 },
];

// La base estable queda cubierta por el compromiso (se factura todas las horas) y los picos van bajo demanda.
export const uso = [
  { item: "savings-plan", quantity: 4 * 720 },
  { item: "bajo-demanda", quantity: 150 },
];

