// Plan de cómputo mensual (720 horas). Precios FICTICIOS del enunciado (USD por hora-instancia).
export const plan: { priceTable: { item: string; unit: string; pricePerUnitUsd: number }[]; usage: { item: string; quantity: number }[] } = {
  priceTable: [
    { item: "bajo-demanda-grande", unit: "hora-instancia", pricePerUnitUsd: 0.2 },
    { item: "bajo-demanda-mediana", unit: "hora-instancia", pricePerUnitUsd: 0.1 },
    { item: "savings-plan-mediana", unit: "hora-instancia", pricePerUnitUsd: 0.07 },
    { item: "spot-mediana", unit: "hora-instancia", pricePerUnitUsd: 0.03 },
  ],
  usage: [
    { item: "savings-plan-mediana", quantity: 2 * 720 + 720 },
    { item: "spot-mediana", quantity: 300 },
    { item: "bajo-demanda-mediana", quantity: 80 },
  ],
};

spec.code:
const resultado = aws.cost.estimate(plan);
assert.deepStrictEqual(resultado.problems, []);
assert.strictEqual(resultado.lines.length, 3, "El plan debe usar una opción de compra por tipo de carga");

const resultado = aws.cost.estimate(plan);
assert.ok(resultado.lines.length > 0, "El plan no tiene ningún uso");
assert.ok(resultado.totalUsd <= 170, "El plan cuesta " + resultado.totalUsd + " USD y el presupuesto es de 170");

assert.deepStrictEqual(plan.priceTable, [
  { item: "bajo-demanda-grande", unit: "hora-instancia", pricePerUnitUsd: 0.2 },
  { item: "bajo-demanda-mediana", unit: "hora-instancia", pricePerUnitUsd: 0.1 },
  { item: "savings-plan-mediana", unit: "hora-instancia", pricePerUnitUsd: 0.07 },
  { item: "spot-mediana", unit: "hora-instancia", pricePerUnitUsd: 0.03 },
]);
